class Solution {
    public int lengthOfLastWord(String s) {
        int i = s.length() - 1;
        while (i >= 0 && s.charAt(i) == ' ') {
            i--;
        }
        int end = i;
        while (i >= 0 && s.charAt(i) != ' ') {
            i--;
        }
        return end - i;
    }
}

class Solution {
    public int lengthOfLastWord(String s) {
        int current = 0;
        int last = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == ' ') {
                if (current > 0) {
                    last = current;
                    current = 0;
                }
            } else {
                current++;
            }
        }
        return current > 0 ? current : last;
    }
}

class Solution {
    public int lengthOfLastWord(String s) {
        String trimmed = s.trim();
        int lastSpace = trimmed.lastIndexOf(' ');
        return trimmed.length() - lastSpace - 1;
    }
}

class Solution {
    private static final java.util.regex.Pattern LAST_WORD = java.util.regex.Pattern.compile("[^ ]+ *$");

    public int lengthOfLastWord(String s) {
        java.util.regex.Matcher matcher = LAST_WORD.matcher(s);
        if (matcher.find()) {
            return matcher.group().trim().length();
        }
        return 0;
    }
}

class Solution {
    public int lengthOfLastWord(String s) {
        String[] words = s.trim().split(" +");
        return words[words.length - 1].length();
    }
}
